<?php
namespace ZinCelestial\Platform\Governance;use InvalidArgumentException;defined('ABSPATH')||exit;
final class GovernancePolicy{public function __construct(private string $id,private string $operation,private array $required_roles,private int $min_approvals=1,private bool $separation=true){$this->id=sanitize_key($id);$this->operation=sanitize_key($operation);if(!$this->id||$min_approvals<1)throw new InvalidArgumentException('Invalid governance policy.');}public function id():string{return$this->id;}public function operation():string{return$this->operation;}public function evaluate(array $approvals,int $requester):bool{$actors=[];foreach($approvals as $a){if(($a['operation']??'')!==$this->operation)continue;$actor=(int)($a['actor']??0);if($this->separation&&$actor===$requester)continue;if(!array_intersect((array)($a['roles']??[]),$this->required_roles))continue;$actors[$actor]=true;}return count($actors)>=$this->min_approvals;}}
